package com.pcopi.passwordvault;

import android.app.*;import android.content.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.os.*;import android.text.InputType;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;

public class MainActivity extends Activity{
 static final int BLUE=Color.rgb(21,101,255),BG=Color.rgb(247,249,252),TEXT=Color.rgb(28,37,54),MUTED=Color.rgb(105,116,133); VaultStore store;String master="";LinearLayout root,list;EditText search;String pending="";final int EXP=7,IMP=8;
 int d(float n){return(int)(n*getResources().getDisplayMetrics().density+.5f);} TextView text(String s,float z,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);v.setGravity(Gravity.CENTER_VERTICAL);return v;} GradientDrawable bg(int c,float r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(d(r));return g;} GradientDrawable outline(int c){GradientDrawable g=bg(Color.WHITE,14);g.setStroke(d(1),c);return g;}
 Button button(String s){Button b=new Button(this);b.setText(s);b.setTextSize(14);b.setTextColor(Color.WHITE);b.setAllCaps(false);b.setBackground(bg(BLUE,14));return b;} EditText input(String h){EditText e=new EditText(this);e.setHint(h);e.setTextSize(15);e.setTextColor(TEXT);e.setHintTextColor(Color.rgb(150,158,170));e.setPadding(d(14),0,d(14),0);e.setBackground(outline(Color.rgb(222,227,235)));return e;}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);store=new VaultStore(this);if(store.initialized())lock();else setup();}
 @Override protected void onStop(){super.onStop();if(!isChangingConfigurations()&&master.length()>0){master="";}}
 void shell(){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(BG);setContentView(root);}
 void setup(){shell();root.addView(text("🔐",56,BLUE),new LinearLayout.LayoutParams(-1,d(90)));TextView t=text("My Password Vault",27,TEXT);t.setGravity(17);t.setTypeface(null,1);root.addView(t,new LinearLayout.LayoutParams(-1,d(45)));TextView s=text("เก็บ Username และ Password อย่างปลอดภัย",15,MUTED);s.setGravity(17);root.addView(s,new LinearLayout.LayoutParams(-1,d(40)));LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(d(20),d(18),d(20),d(18));box.setBackground(bg(Color.WHITE,20));LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,d(205));bp.setMargins(d(18),d(20),d(18),0);root.addView(box,bp);EditText p=input("สร้าง Master Password (อย่างน้อย 6 ตัวอักษร)");p.setInputType(129);box.addView(p,new LinearLayout.LayoutParams(-1,d(55)));EditText c=input("ยืนยัน Master Password");c.setInputType(129);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,d(55));cp.setMargins(0,d(10),0,0);box.addView(c,cp);Button go=button("เริ่มใช้งาน");LinearLayout.LayoutParams gp=new LinearLayout.LayoutParams(-1,d(50));gp.setMargins(0,d(14),0,0);box.addView(go,gp);go.setOnClickListener(v->{String a=p.getText().toString(),x=c.getText().toString();if(a.length()<6){toast("รหัสผ่านต้องมีอย่างน้อย 6 ตัวอักษร");return;}if(!a.equals(x)){toast("รหัสผ่านยืนยันไม่ตรงกัน");return;}try{store.initialize(a);master=a;home();}catch(Exception e){toast("สร้าง Vault ไม่สำเร็จ");}});}
 void lock(){shell();root.addView(text("🔒",55,BLUE),new LinearLayout.LayoutParams(-1,d(105)));TextView t=text("My Password Vault",26,TEXT);t.setGravity(17);t.setTypeface(null,1);root.addView(t,new LinearLayout.LayoutParams(-1,d(45)));TextView s=text("กรุณาใส่ Master Password เพื่อเข้าใช้งาน",15,MUTED);s.setGravity(17);root.addView(s,new LinearLayout.LayoutParams(-1,d(45)));LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(d(20),d(18),d(20),d(18));box.setBackground(bg(Color.WHITE,20));LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,d(145));bp.setMargins(d(18),d(20),d(18),0);root.addView(box,bp);EditText p=input("รหัสผ่าน");p.setInputType(129);box.addView(p,new LinearLayout.LayoutParams(-1,d(55)));Button go=button("เข้าสู่ระบบ");LinearLayout.LayoutParams gp=new LinearLayout.LayoutParams(-1,d(50));gp.setMargins(0,d(12),0,0);box.addView(go,gp);go.setOnClickListener(v->{if(store.unlock(p.getText().toString())){master=p.getText().toString();home();}else p.setError("รหัสผ่านไม่ถูกต้อง");});}
 void home(){shell();LinearLayout h=new LinearLayout(this);h.setGravity(Gravity.CENTER_VERTICAL);h.setPadding(d(15),d(6),d(10),0);TextView menu=text("☰",27,TEXT);h.addView(menu,new LinearLayout.LayoutParams(d(42),d(52)));TextView title=text("My Password Vault",19,TEXT);title.setTypeface(null,1);h.addView(title,new LinearLayout.LayoutParams(0,d(52),1));TextView lock=text("🔒",20,MUTED);h.addView(lock,new LinearLayout.LayoutParams(d(45),d(52)));root.addView(h);lock.setOnClickListener(v->{master="";lock();});search=input("ค้นหา ชื่อรายการ, username หรือหมายเหตุ...");search.setSingleLine(true);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,d(50));sp.setMargins(d(14),d(3),d(14),d(8));root.addView(search,sp);search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void onTextChanged(CharSequence s,int a,int b,int c){render(s.toString());}public void afterTextChanged(android.text.Editable e){}});list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);ScrollView sv=new ScrollView(this);sv.addView(list);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));Button add=button("＋  เพิ่มรายการ");LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-1,d(54));ap.setMargins(d(14),d(6),d(14),d(6));root.addView(add,ap);add.setOnClickListener(v->edit(null));LinearLayout nav=new LinearLayout(this);nav.setGravity(Gravity.CENTER);nav.setBackgroundColor(Color.WHITE);String[] n={"รายการ","หมวดหมู่","สำรองข้อมูล","ตั้งค่า"};for(int i=0;i<4;i++){TextView q=text(n[i],11,MUTED);q.setGravity(17);final int z=i;nav.addView(q,new LinearLayout.LayoutParams(0,d(55),1));q.setOnClickListener(v->{if(z==0)home();else if(z==1)categories();else if(z==2)backup();else settings();});}root.addView(nav);render("");menu.setOnClickListener(v->backup());}
 void render(String q){list.removeAllViews();List<VaultStore.Entry> es=store.entries(master);q=q.toLowerCase(Locale.ROOT);int no=0;for(VaultStore.Entry e:es){if(!(e.title+" "+e.user+" "+e.note).toLowerCase(Locale.ROOT).contains(q))continue;no++;LinearLayout c=new LinearLayout(this);c.setGravity(Gravity.CENTER_VERTICAL);c.setPadding(d(12),d(7),d(7),d(7));c.setBackground(bg(Color.WHITE,16));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,d(76));cp.setMargins(d(12),d(5),d(12),d(5));list.addView(c,cp);TextView num=text(String.format(Locale.US,"%02d",no),12,BLUE);num.setGravity(17);num.setBackground(bg(Color.rgb(231,239,255),30));c.addView(num,new LinearLayout.LayoutParams(d(38),d(38)));LinearLayout tx=new LinearLayout(this);tx.setOrientation(LinearLayout.VERTICAL);tx.setPadding(d(12),0,0,0);TextView a=text(e.title,16,TEXT);a.setTypeface(null,1);tx.addView(a,new LinearLayout.LayoutParams(-1,d(30)));tx.addView(text(e.user,12,MUTED),new LinearLayout.LayoutParams(-1,d(25)));c.addView(tx,new LinearLayout.LayoutParams(0,-1,1));c.addView(text("›",28,MUTED),new LinearLayout.LayoutParams(d(32),-1));c.setOnClickListener(v->details(e));}if(no==0){TextView empty=text("ยังไม่มีรายการ\nกด “เพิ่มรายการ” เพื่อเริ่มต้น",16,MUTED);empty.setGravity(17);list.addView(empty,new LinearLayout.LayoutParams(-1,d(160)));}}
 void details(VaultStore.Entry e){shell();bar("รายละเอียดรายการ",()->home());LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(d(18),d(12),d(18),d(20));root.addView(box);TextView h=text(e.title,23,TEXT);h.setTypeface(null,1);box.addView(h,new LinearLayout.LayoutParams(-1,d(50)));showField(box,"Username",e.user,true,false);showField(box,"Password",e.pass,true,true);showField(box,"บันทึกเพิ่มเติม",e.note,false,false);showField(box,"หมวดหมู่",e.category,false,false);Button ed=button("✎  แก้ไข");box.addView(ed,new LinearLayout.LayoutParams(-1,d(52)));ed.setOnClickListener(v->edit(e));Button de=button("ลบรายการ");de.setTextColor(Color.rgb(190,40,55));de.setBackground(outline(Color.rgb(240,200,205)));LinearLayout.LayoutParams dp=new LinearLayout.LayoutParams(-1,d(52));dp.setMargins(0,d(10),0,0);box.addView(de,dp);de.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("ลบรายการ?").setMessage(e.title).setNegativeButton("ยกเลิก",null).setPositiveButton("ลบ",(x,w)->{try{store.delete(master,e.id);home();}catch(Exception z){toast("ลบไม่สำเร็จ");}}).show());}
 void showField(LinearLayout b,String lab,String value,boolean cp,boolean pw){b.addView(text(lab,12,MUTED),new LinearLayout.LayoutParams(-1,d(28)));LinearLayout r=new LinearLayout(this);r.setGravity(Gravity.CENTER_VERTICAL);r.setPadding(d(12),0,d(5),0);r.setBackground(outline(Color.rgb(230,234,240)));TextView v=text(pw?"••••••••••":(value.isEmpty()?"-":value),15,TEXT);r.addView(v,new LinearLayout.LayoutParams(0,d(50),1));if(pw){TextView eye=text("👁",18,MUTED);r.addView(eye,new LinearLayout.LayoutParams(d(42),d(50)));eye.setOnClickListener(x->v.setText(v.getText().toString().startsWith("•")?value:"••••••••••"));}if(cp){TextView c=text("📋",18,MUTED);r.addView(c,new LinearLayout.LayoutParams(d(42),d(50)));c.setOnClickListener(x->copy(value));}b.addView(r,new LinearLayout.LayoutParams(-1,d(52)));}
 void edit(VaultStore.Entry old){VaultStore.Entry e=old==null?VaultStore.newEntry():new VaultStore.Entry(old.id,old.title,old.user,old.pass,old.note,old.category);shell();bar(old==null?"เพิ่มรายการ":"แก้ไขรายการ",()->home());LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(d(16),0,d(16),d(20));ScrollView sv=new ScrollView(this);sv.addView(box);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));EditText a=input("ชื่อรายการ");a.setText(e.title);box.addView(text("รายการ",12,MUTED));box.addView(a,new LinearLayout.LayoutParams(-1,d(52)));EditText u=input("Username");u.setText(e.user);box.addView(text("Username",12,MUTED));box.addView(u,new LinearLayout.LayoutParams(-1,d(52)));EditText p=input("Password");p.setText(e.pass);p.setInputType(129);box.addView(text("Password",12,MUTED));box.addView(p,new LinearLayout.LayoutParams(-1,d(52)));EditText n=input("บันทึกเพิ่มเติม");n.setText(e.note);n.setMinLines(3);box.addView(text("บันทึกเพิ่มเติม",12,MUTED));box.addView(n,new LinearLayout.LayoutParams(-1,d(90)));EditText cat=input("หมวดหมู่ เช่น ทั่วไป / อีเมล / ธนาคาร");cat.setText(e.category);box.addView(text("หมวดหมู่",12,MUTED));box.addView(cat,new LinearLayout.LayoutParams(-1,d(52)));Button save=button("💾  บันทึก");LinearLayout.LayoutParams sb=new LinearLayout.LayoutParams(-1,d(52));sb.setMargins(0,d(18),0,0);box.addView(save,sb);save.setOnClickListener(v->{e.title=a.getText().toString().trim();e.user=u.getText().toString();e.pass=p.getText().toString();e.note=n.getText().toString();e.category=cat.getText().toString();if(e.title.isEmpty()){a.setError("กรุณาระบุชื่อรายการ");return;}try{if(old==null)store.add(master,e);else store.update(master,e);toast("บันทึกเรียบร้อย");home();}catch(Exception x){toast("บันทึกไม่สำเร็จ");}});}
 void categories(){shell();bar("หมวดหมู่",()->home());LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);b.setPadding(d(14),d(8),d(14),d(20));root.addView(b);Map<String,Integer> m=new LinkedHashMap<>();for(VaultStore.Entry e:store.entries(master)){String c=e.category==null||e.category.isEmpty()?"ทั่วไป":e.category;m.put(c,m.getOrDefault(c,0)+1);}for(Map.Entry<String,Integer>x:m.entrySet()){LinearLayout r=new LinearLayout(this);r.setGravity(Gravity.CENTER_VERTICAL);r.setPadding(d(15),0,d(15),0);r.setBackground(bg(Color.WHITE,15));TextView name=text("▦   "+x.getKey(),16,TEXT);r.addView(name,new LinearLayout.LayoutParams(0,d(62),1));r.addView(text(String.valueOf(x.getValue()),14,MUTED),new LinearLayout.LayoutParams(d(35),d(62)));LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,d(68));rp.setMargins(0,d(5),0,d(5));b.addView(r,rp);}}
 void backup(){shell();bar("สำรองข้อมูล",()->home());LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);b.setPadding(d(14),d(8),d(14),d(20));root.addView(b);TextView info=text("🔐 Backup ถูกเข้ารหัสด้วย Master Password ก่อนบันทึก",14,TEXT);info.setPadding(d(14),d(12),d(14),d(12));info.setBackground(bg(Color.rgb(232,241,255),15));b.addView(info,new LinearLayout.LayoutParams(-1,d(70)));Button ex=button("☁  สำรองไป Google Drive / ไฟล์");b.addView(ex,new LinearLayout.LayoutParams(-1,d(54)));ex.setOnClickListener(v->exportBackup());Button im=button("♻  กู้คืนจาก Google Drive / ไฟล์");im.setTextColor(BLUE);im.setBackground(outline(Color.rgb(185,207,255)));LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(-1,d(54));ip.setMargins(0,d(10),0,d(20));b.addView(im,ip);im.setOnClickListener(v->importBackup());TextView h=text("Synology NAS • WebDAV",18,TEXT);h.setTypeface(null,1);b.addView(h,new LinearLayout.LayoutParams(-1,d(45)));EditText url=input("https://NAS:5006/backup");EditText user=input("ชื่อผู้ใช้ NAS");EditText pass=input("รหัสผ่าน NAS");pass.setInputType(129);b.addView(url,new LinearLayout.LayoutParams(-1,d(52)));b.addView(user,new LinearLayout.LayoutParams(-1,d(52)));b.addView(pass,new LinearLayout.LayoutParams(-1,d(52)));Button up=button("☁  สำรองไป Synology NAS");LinearLayout.LayoutParams upP=new LinearLayout.LayoutParams(-1,d(54));upP.setMargins(0,d(12),0,0);b.addView(up,upP);up.setOnClickListener(v->new Thread(()->{try{String fn="PasswordManager_"+new java.text.SimpleDateFormat("yyyyMMdd_HHmmss",Locale.US).format(new Date())+".pmb";BackupManager.upload(url.getText().toString(),user.getText().toString(),pass.getText().toString(),fn,store.encryptedBackup(master));runOnUiThread(()->toast("สำรอง Synology สำเร็จ"));}catch(Exception x){runOnUiThread(()->toast("NAS ไม่สำเร็จ: "+x.getMessage()));}}).start());}
 void exportBackup(){try{pending=store.encryptedBackup(master);Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/octet-stream");i.putExtra(Intent.EXTRA_TITLE,"PasswordManager_Backup.pmb");startActivityForResult(i,EXP);}catch(Exception e){toast("สร้าง Backup ไม่สำเร็จ");}}
 void importBackup(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,IMP);}
 @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(c!=RESULT_OK||d==null)return;try{if(r==EXP){OutputStream o=getContentResolver().openOutputStream(d.getData());o.write(pending.getBytes("UTF-8"));o.close();toast("บันทึก Backup สำเร็จ");}else{InputStream in=getContentResolver().openInputStream(d.getData());ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] z=new byte[8192];int n;while((n=in.read(z))>0)out.write(z,0,n);in.close();store.restoreEncryptedBackup(out.toString("UTF-8"),master);toast("กู้คืนข้อมูลสำเร็จ");home();}}catch(Exception e){toast("ดำเนินการไม่สำเร็จ: "+e.getMessage());}}
 void settings(){shell();bar("ตั้งค่า",()->home());LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);b.setPadding(d(14),d(10),d(14),d(20));root.addView(b);Button ch=button("🔑  เปลี่ยน Master Password");b.addView(ch,new LinearLayout.LayoutParams(-1,d(54)));ch.setOnClickListener(v->changeMaster());TextView t=text("🔒  แอปจะล็อกทุกครั้งเมื่อออกจากแอป\n\nข้อมูลในเครื่องเข้ารหัสด้วย AES-GCM\nGoogle Drive ใช้ตัวเลือกไฟล์ของ Android\nSynology รองรับ WebDAV",14,MUTED);t.setPadding(d(8),d(20),d(8),0);b.addView(t);}
 void changeMaster(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);EditText o=input("Master Password เดิม");o.setInputType(129);EditText n=input("Master Password ใหม่");n.setInputType(129);EditText c=input("ยืนยันรหัสใหม่");c.setInputType(129);l.addView(o);l.addView(n);l.addView(c);new AlertDialog.Builder(this).setTitle("เปลี่ยน Master Password").setView(l).setNegativeButton("ยกเลิก",null).setPositiveButton("บันทึก",(d,w)->{if(!store.unlock(o.getText().toString())){toast("รหัสเดิมไม่ถูกต้อง");return;}if(n.getText().length()<6||!n.getText().toString().equals(c.getText().toString())){toast("รหัสใหม่ไม่ถูกต้อง");return;}try{List<VaultStore.Entry> es=store.entries(master);store.initialize(n.getText().toString());store.saveEntries(n.getText().toString(),es);master=n.getText().toString();toast("เปลี่ยนรหัสสำเร็จ");}catch(Exception e){toast("เปลี่ยนรหัสไม่สำเร็จ");}}).show();}
 void bar(String s,Runnable back){LinearLayout h=new LinearLayout(this);h.setGravity(Gravity.CENTER_VERTICAL);TextView x=text("‹",38,TEXT);x.setGravity(17);h.addView(x,new LinearLayout.LayoutParams(d(48),d(55)));TextView t=text(s,20,TEXT);t.setTypeface(null,1);h.addView(t,new LinearLayout.LayoutParams(0,d(55),1));root.addView(h);x.setOnClickListener(v->back.run());}void copy(String s){((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Password",s));toast("คัดลอกแล้ว");}void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
}
